const LOCAL_KEY='chargeflow_entries_v1';
const SUPABASE_URL='https://sxhdzdrgvgoxazcoguyx.supabase.co';
const SUPABASE_KEY='sb_publishable_NThhpaesI2pnF8uXWpmNaA_qoQwmsp2';
let entries=[],loading=true,dbError='';
let mode='kwh',period='all',exactDate='',page=1;
const PAGE_SIZE=6,PRICE=120,POWER_COST=50,SERVICE_RATE=.15,TAX_RATE=.10;
const app=document.querySelector('#app');
async function supabase(path,options={}){const response=await fetch(`${SUPABASE_URL}/rest/v1/${path}`,{...options,headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${SUPABASE_KEY}`,'Content-Type':'application/json',...(options.headers||{})}});const body=await response.text();if(!response.ok){let error={};try{error=body?JSON.parse(body):{}}catch{}throw new Error(error.message||error.hint||error.details||`Supabase սխալ՝ ${response.status}`)}return body?JSON.parse(body):null}
function fromRow(row){return{id:row.id,date:row.charge_date,kwh:Number(row.kwh),type:row.connector_type}}
async function fetchAll(){const all=[];for(let offset=0;;offset+=1000){const batch=await supabase(`charging_sessions?select=id,charge_date,kwh,connector_type,created_at&order=charge_date.desc,created_at.desc&offset=${offset}&limit=1000`);all.push(...batch);if(batch.length<1000)break}return all.map(fromRow)}
async function migrateLocalData(){const local=JSON.parse(localStorage.getItem(LOCAL_KEY)||'null');if(!Array.isArray(local))return;const real=local.filter(e=>/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(e.id)&&e.date&&Number(e.kwh)>0&&['GB/T','CCS1'].includes(e.type));if(!real.length){localStorage.removeItem(LOCAL_KEY);return}await supabase('charging_sessions?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify(real.map(e=>({id:e.id,charge_date:e.date,kwh:Number(e.kwh),connector_type:e.type})))});localStorage.removeItem(LOCAL_KEY)}
async function loadEntries(){loading=true;dbError='';render();try{await migrateLocalData();entries=await fetchAll()}catch(error){dbError=error.message||'Չհաջողվեց միանալ Supabase-ին'}finally{loading=false;render()}}
async function addSession(data){const rows=await supabase('charging_sessions',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({charge_date:data.date,kwh:data.kwh,connector_type:data.type})});const item=fromRow(rows[0]);entries.unshift(item);return item}
async function removeSession(id){await supabase(`charging_sessions?id=eq.${encodeURIComponent(id)}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});entries=entries.filter(e=>e.id!==id)}
function fmt(n,d=1){return Number(n).toLocaleString('hy-AM',{maximumFractionDigits:d})}
function money(n){return `${Math.round(n).toLocaleString('hy-AM')} ֏`}
function iso(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function dateLabel(s,long=false){return new Intl.DateTimeFormat('hy-AM',long?{year:'numeric',month:'short',day:'numeric'}:{month:'short',day:'numeric'}).format(new Date(s+'T00:00:00'))}
function rangeFor(p){const now=new Date(),end=iso(now);if(p==='today')return[end,end];if(p==='week'){const start=new Date(now);start.setDate(start.getDate()-(start.getDay()+6)%7);return[iso(start),end]}if(p==='month')return[`${end.slice(0,7)}-01`,end];return[null,null]}
function filtered(){if(period==='date'&&exactDate)return entries.filter(e=>e.date===exactDate);const[start,end]=rangeFor(period);return start?entries.filter(e=>e.date>=start&&e.date<=end):entries}
function daily(list){const m={};list.forEach(e=>{m[e.date]??={date:e.date,kwh:0,cars:0};m[e.date].kwh+=+e.kwh;m[e.date].cars++});return Object.values(m).sort((a,b)=>a.date.localeCompare(b.date))}
function trend(vals){if(vals.length<2)return 0;const split=Math.ceil(vals.length/2),a=vals.slice(0,split).reduce((x,y)=>x+y,0),b=vals.slice(split).reduce((x,y)=>x+y,0);return a?((b-a)/a)*100:0}
function trendHTML(v){return `<span class="trend ${v<0?'down':''}">${v>=0?'↗':'↘'} ${Math.abs(v).toFixed(1)}%</span>`}
function periodText(){if(period==='today')return'Այսօր';if(period==='week')return'Այս շաբաթ';if(period==='month')return'Այս ամիս';if(period==='date'&&exactDate)return dateLabel(exactDate,true);return'Ամբողջ ժամանակահատվածը'}
function pager(current,total){const wanted=new Set([1,total,current-1,current,current+1]);const pages=[...wanted].filter(n=>n>=1&&n<=total).sort((a,b)=>a-b);let out='',prev=0;for(const n of pages){if(prev&&n-prev>1)out+='<span class="page-gap">…</span>';out+=`<button class="page-btn ${current===n?'active':''}" data-page="${n}">${n}</button>`;prev=n}return out}
function renderChart(data,key){
  if(!data.length)return '<div class="empty chart-empty"><span>⌁</span><b>Այս ժամանակահատվածում տվյալներ չկան</b><small>Փոխիր ֆիլտրը կամ ավելացրու լիցքավորում</small></div>';
  const w=760,h=260,p={l:46,r:18,t:22,b:38},vals=data.map(x=>x[key]),max=Math.max(...vals,1)*1.18;
  const x=i=>data.length===1?(p.l+w-p.r)/2:p.l+(i/(data.length-1))*(w-p.l-p.r),y=v=>h-p.b-(v/max)*(h-p.t-p.b);
  const pts=data.map((d,i)=>`${x(i)},${y(d[key])}`).join(' '),area=`${x(0)},${h-p.b} ${pts} ${x(data.length-1)},${h-p.b}`;
  const grids=[0,.25,.5,.75,1].map(t=>`<line class="grid-line" x1="${p.l}" y1="${y(max*t)}" x2="${w-p.r}" y2="${y(max*t)}"/><text class="axis-label" x="3" y="${y(max*t)+4}">${fmt(max*t,0)}</text>`).join('');
  const step=Math.max(1,Math.ceil(data.length/6)),labels=data.map((d,i)=>i%step===0||i===data.length-1?`<text class="axis-label" text-anchor="middle" x="${x(i)}" y="${h-9}">${dateLabel(d.date)}</text>`:'').join('');
  const points=data.map((d,i)=>`<g class="chart-point" tabindex="0" data-date="${d.date}" data-kwh="${d.kwh}" data-cars="${d.cars}" data-x="${x(i)}" data-y="${y(d[key])}"><line class="hover-line" x1="${x(i)}" y1="${p.t}" x2="${x(i)}" y2="${h-p.b}"/><circle class="dot-halo" cx="${x(i)}" cy="${y(d[key])}" r="10"/><circle class="dot" cx="${x(i)}" cy="${y(d[key])}" r="4"/><circle class="hit" cx="${x(i)}" cy="${y(d[key])}" r="18"/></g>`).join('');
  return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${key==='kwh'?'Վաճառված կիլովատների':'Մեքենաների քանակի'} գրաֆիկ"><defs><linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#5ee6a8" stop-opacity=".30"/><stop offset="1" stop-color="#5ee6a8" stop-opacity="0"/></linearGradient></defs>${grids}<polygon class="area" points="${area}"/><polyline class="chart-line" points="${pts}"/>${points}${labels}</svg><div class="chart-tooltip" id="chartTooltip" hidden><strong></strong><div><span>Վաճառք</span><b class="tip-kwh"></b></div><div><span>Մեքենաներ</span><b class="tip-cars"></b></div></div>`;
}
function render(){
  if(loading){app.innerHTML='<div class="shell"><header class="topbar"><div class="brand"><div class="bolt">ϟ</div><div><h1>ChargeFlow</h1><p>Supabase-ից բեռնվում է</p></div></div></header><section class="loading-grid"><div class="skeleton wide"></div><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></section></div>';return}
  if(dbError){app.innerHTML=`<div class="state-screen"><div class="bolt">!</div><h1>Supabase կապը դեռ պատրաստ չէ</h1><p>${dbError}</p><p class="state-hint">Supabase SQL Editor-ում աշխատեցրու ստացած SQL-ը, հետո նորից փորձիր։</p><button class="btn primary" id="retry">Նորից փորձել</button></div>`;document.querySelector('#retry').onclick=loadEntries;return}
  const shown=filtered(),days=daily(shown),total=shown.reduce((s,e)=>s+ +e.kwh,0),avg=shown.length?total/shown.length:0,kTrend=trend(days.map(x=>x.kwh)),cTrend=trend(days.map(x=>x.cars));
  const revenue=total*PRICE,service=revenue*SERVICE_RATE,taxBase=revenue-service,tax=taxBase*TAX_RATE,power=total*POWER_COST,net=revenue-service-tax-power;
  const types={'GB/T':0,'CCS1':0};shown.forEach(e=>types[e.type]=(types[e.type]||0)+1);const typeTotal=Math.max(shown.length,1),gb=Math.round(types['GB/T']/typeTotal*100);
  const sorted=[...shown].sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id)),pageCount=Math.max(1,Math.ceil(sorted.length/PAGE_SIZE));page=Math.min(page,pageCount);const rows=sorted.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE);
  app.innerHTML=`<div class="shell"><header class="topbar"><div class="brand"><div class="bolt">ϟ</div><div><h1>ChargeFlow</h1><p>Արագ լիցքավորման վերլուծություն</p></div></div><div class="actions"><span class="sync-status"><i></i> Supabase</span><button class="btn" id="export">⇩ <span class="label">Արտահանել CSV</span></button><button class="btn primary" id="add">＋ <span class="label">Նոր լիցքավորում</span></button></div></header>
  <section class="filterbar"><div class="quick-filters">${[['all','Բոլորը'],['today','Այսօր'],['week','Այս շաբաթ'],['month','Այս ամիս']].map(([v,l])=>`<button class="filter-chip ${period===v?'active':''}" data-period="${v}">${l}</button>`).join('')}</div><div class="date-filter"><span>Կոնկրետ օր</span><input id="exactDate" type="date" value="${exactDate}" aria-label="Ընտրել կոնկրետ օր"><button class="clear-date" id="clearDate" ${period!=='date'?'hidden':''} aria-label="Մաքրել ամսաթիվը">×</button></div><div class="filter-result"><b>${periodText()}</b><span>${shown.length} լիցքավորում</span></div></section>
  <section class="grid"><article class="card stat"><div class="eyebrow"><span>Վաճառված էներգիա</span>${trendHTML(kTrend)}</div><div class="metric">${fmt(total)} <small>կՎտ⋅ժ</small></div><div class="sub">Ընտրված ժամանակահատվածում</div></article>
  <article class="card stat"><div class="eyebrow"><span>Մեքենաների քանակ</span>${trendHTML(cTrend)}</div><div class="metric">${shown.length}</div><div class="sub">Յուրաքանչյուր գրառում՝ 1 մեքենա</div></article>
  <article class="card stat"><div class="eyebrow"><span>Միջին լիցքավորում</span><span>∿</span></div><div class="metric">${fmt(avg)} <small>կՎտ⋅ժ</small></div><div class="sub">Մեկ մեքենայի հաշվով</div></article>
  <article class="card stat"><div class="eyebrow"><span>Ակտիվ օրեր</span><span>◷</span></div><div class="metric">${days.length}</div><div class="sub">Տվյալներով օրերի քանակ</div></article>
  <article class="card finance-card"><div class="finance-head"><div><h2>Ֆինանսական հաշվարկ</h2><p>${periodText()} · ${fmt(total)} կՎտ⋅ժ</p></div></div><div class="finance-steps"><div class="finance-step income"><span>Ընդհանուր շրջանառություն</span><b>${money(revenue)}</b><small>${fmt(total)} × 120 ֏</small></div><div class="finance-step"><span>Գործընկերոջ սպասարկում՝ 15%</span><b>− ${money(service)}</b><small>Ընդհանուր շրջանառությունից</small></div><div class="finance-step"><span>Եկամտահարկ՝ 10%</span><b>− ${money(tax)}</b><small>15%-ը հանելուց հետո</small></div><div class="finance-step"><span>ՀԷՑ-ի վճար</span><b>− ${money(power)}</b><small>${fmt(total)} × 50 ֏</small></div><div class="finance-step result"><span>Մաքուր մնացորդ</span><b>= ${money(net)}</b><small>Վերջնական հաշվարկ</small></div></div></article>
  <article class="card chart-card"><div class="card-head"><div><h2>Վաճառքի շարժ</h2><p>Պահիր կուրսորը կետի վրա՝ մանրամասները տեսնելու համար</p></div><div class="tabs"><button class="tab ${mode==='kwh'?'active':''}" data-mode="kwh">կՎտ⋅ժ</button><button class="tab ${mode==='cars'?'active':''}" data-mode="cars">Մեքենաներ</button></div></div><div class="chart-wrap">${renderChart(days,mode)}</div></article>
  <article class="card type-card"><div class="card-head"><div><h2>Միակցիչների բաժանում</h2><p>Ըստ լիցքավորումների քանակի</p></div></div><div class="donut-wrap"><div class="donut" style="background:conic-gradient(var(--green) 0 ${gb}%,var(--blue) ${gb}% 100%)"></div><div class="donut-center"><b>${shown.length}</b><span>լիցքավորում</span></div></div><div class="legend"><div class="legend-row"><span><i class="swatch"></i>GB/T</span><b>${types['GB/T']} · ${Math.round(types['GB/T']/typeTotal*100)}%</b></div><div class="legend-row"><span><i class="swatch blue"></i>CCS1</span><b>${types.CCS1} · ${Math.round(types.CCS1/typeTotal*100)}%</b></div></div></article>
  <article class="card table-card"><div class="card-head"><div><h2>Վերջին լիցքավորումները</h2><p>${sorted.length?`${(page-1)*PAGE_SIZE+1}–${Math.min(page*PAGE_SIZE,sorted.length)}՝ ${sorted.length} գրառումից`:'Ընտրված ժամանակահատվածում'}</p></div></div><div class="table-scroll">${rows.length?`<table><thead><tr><th>Ամսաթիվ</th><th>Էներգիա</th><th>Type</th><th>Շրջանառություն</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td data-label="Ամսաթիվ">${dateLabel(e.date,true)}</td><td data-label="Էներգիա"><b>${fmt(e.kwh)} կՎտ⋅ժ</b></td><td data-label="Միակցիչ"><span class="badge ${e.type==='GB/T'?'green':''}">${e.type}</span></td><td data-label="Շրջանառություն">${money(e.kwh*PRICE)}</td><td class="row-action"><button class="icon-btn delete" data-id="${e.id}" aria-label="Ջնջել">×</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Այս ֆիլտրով լիցքավորում չի գտնվել</div>'}</div>${sorted.length>PAGE_SIZE?`<nav class="pagination" aria-label="Էջեր"><button class="page-btn" data-page="${page-1}" ${page===1?'disabled':''}>‹</button>${pager(page,pageCount)}<button class="page-btn" data-page="${page+1}" ${page===pageCount?'disabled':''}>›</button></nav>`:''}</article></section></div>
  <div class="modal" id="modal" hidden><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><div class="dialog-head"><h2 id="dialogTitle">Նոր լիցքավորում</h2><button class="icon-btn" id="close" aria-label="Փակել">×</button></div><form class="form" id="form"><div class="field"><label for="date">Ամսաթիվ</label><input id="date" name="date" type="date" required></div><div class="field"><label for="kwh">Վաճառված էներգիա (կՎտ⋅ժ)</label><input id="kwh" name="kwh" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="օր.՝ 25.55" required></div><div class="field"><label for="type">Միակցիչի տեսակը</label><select id="type" name="type"><option>GB/T</option><option>CCS1</option></select></div><div class="dialog-actions"><button type="button" class="btn" id="cancel">Չեղարկել</button><button class="btn primary" type="submit">Պահպանել</button></div></form></div></div>`;
  bind();
}
function bind(){
  const modal=document.querySelector('#modal'),open=()=>{modal.hidden=false;document.querySelector('#date').value=iso(new Date());document.querySelector('#kwh').focus()},close=()=>modal.hidden=true;
  document.querySelector('#add').onclick=open;document.querySelector('#close').onclick=close;document.querySelector('#cancel').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};
  document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});document.querySelectorAll('.filter-chip').forEach(b=>b.onclick=()=>{period=b.dataset.period;exactDate='';page=1;render()});
  document.querySelector('#exactDate').onchange=e=>{exactDate=e.target.value;period=exactDate?'date':'all';page=1;render()};document.querySelector('#clearDate').onclick=()=>{exactDate='';period='all';page=1;render()};
  document.querySelectorAll('.page-btn[data-page]').forEach(b=>b.onclick=()=>{page=+b.dataset.page;render();document.querySelector('.table-card').scrollIntoView({behavior:'smooth',block:'start'})});
  document.querySelectorAll('.delete').forEach(b=>b.onclick=async()=>{if(!confirm('Ջնջե՞լ այս լիցքավորման տվյալը։'))return;b.disabled=true;try{await removeSession(b.dataset.id);render();toast('Տվյալը ջնջված է')}catch(error){b.disabled=false;toast(error.message||'Չհաջողվեց ջնջել')}});
  document.querySelector('#form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),button=e.target.querySelector('[type="submit"]'),data={date:f.get('date'),kwh:+f.get('kwh'),type:f.get('type')};button.disabled=true;button.textContent='Պահպանվում է…';try{await addSession(data);period='all';exactDate='';page=1;render();toast('Տվյալը պահպանված է Supabase-ում')}catch(error){button.disabled=false;button.textContent='Պահպանել';toast(error.message||'Չհաջողվեց պահպանել')}};document.querySelector('#export').onclick=exportCSV;bindChartHover();
}
function bindChartHover(){const tip=document.querySelector('#chartTooltip'),wrap=document.querySelector('.chart-wrap');if(!tip||!wrap)return;const show=p=>{tip.hidden=false;tip.querySelector('strong').textContent=dateLabel(p.dataset.date,true);tip.querySelector('.tip-kwh').textContent=`${fmt(p.dataset.kwh)} կՎտ⋅ժ`;tip.querySelector('.tip-cars').textContent=`${p.dataset.cars} մեքենա`;const svg=wrap.querySelector('svg'),box=svg.getBoundingClientRect(),vb=svg.viewBox.baseVal;let left=(+p.dataset.x/vb.width)*box.width,top=(+p.dataset.y/vb.height)*box.height;tip.style.left=`${Math.min(Math.max(left,78),box.width-78)}px`;tip.style.top=`${Math.max(top-12,12)}px`;p.classList.add('hovered')},hide=p=>{tip.hidden=true;p.classList.remove('hovered')};wrap.querySelectorAll('.chart-point').forEach(p=>{p.onpointerenter=()=>show(p);p.onpointerleave=()=>hide(p);p.onfocus=()=>show(p);p.onblur=()=>hide(p)})}
function exportCSV(){const list=filtered(),rows=[['date','kwh','type','revenue_amd'],...list.map(e=>[e.date,e.kwh,e.type,e.kwh*PRICE])];const blob=new Blob(['\ufeff'+rows.map(r=>r.join(',')).join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='chargeflow-data.csv';a.click();URL.revokeObjectURL(a.href)}
function toast(t){const x=document.createElement('div');x.className='toast';x.textContent=t;document.body.append(x);setTimeout(()=>x.remove(),2200)}
loadEntries();
function registerAgentTools(){const context=document.modelContext;if(!context?.registerTool)return;const fail=m=>{throw new Error(m)};Promise.resolve(context.registerTool({name:'add_charging_session',title:'Ավելացնել լիցքավորում',description:'Պահպանում է մեկ մեքենայի լիցքավորման տվյալը Supabase-ում և թարմացնում dashboard-ը։',inputSchema:{type:'object',properties:{date:{type:'string',pattern:'^\\d{4}-\\d{2}-\\d{2}$'},kwh:{type:'number',exclusiveMinimum:0},connectorType:{type:'string',enum:['GB/T','CCS1']}},required:['date','kwh','connectorType'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(!input||!/^\d{4}-\d{2}-\d{2}$/.test(input.date||''))fail('Ամսաթիվը պետք է լինի YYYY-MM-DD ձևաչափով։');if(!Number.isFinite(input.kwh)||input.kwh<=0)fail('կՎտ⋅ժ-ը պետք է լինի դրական թիվ։');if(!['GB/T','CCS1'].includes(input.connectorType))fail('Անհայտ միակցիչ։');await addSession({date:input.date,kwh:input.kwh,type:input.connectorType});render();return{saved:true,totalSessions:entries.length}}})).catch(()=>{});Promise.resolve(context.registerTool({name:'read_charging_summary',title:'Կարդալ ամփոփումը',description:'Վերադարձնում է Supabase-ից բեռնված ընթացիկ ֆինանսական և օգտագործման ամփոփումը։',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){const list=filtered(),totalKwh=list.reduce((s,e)=>s+ +e.kwh,0),revenue=totalKwh*PRICE,service=revenue*SERVICE_RATE,tax=(revenue-service)*TAX_RATE,power=totalKwh*POWER_COST;return{period:periodText(),totalKwh:Number(totalKwh.toFixed(1)),totalSessions:list.length,revenueAMD:Math.round(revenue),serviceAMD:Math.round(service),incomeTaxAMD:Math.round(tax),powerCostAMD:Math.round(power),netAMD:Math.round(revenue-service-tax-power)}}})).catch(()=>{})}
registerAgentTools();
